INSERT INTO `knowledge_center` VALUES (1,'30 Week MA - Stage Analysis','Trading View Script','//@version=5\r\nindicator(\"30 Week MA - Stage Analysis\", overlay=true)\r\n\r\nma10  = request.security(syminfo.tickerid,\"D\",ta.ema(close, 10))\r\nma21  = request.security(syminfo.tickerid,\"D\",ta.ema(close, 21))\r\nma50 = request.security(syminfo.tickerid,\"D\",ta.ema(close, 50))\r\nma30w = request.security(syminfo.tickerid,\"W\",ta.ema(close, 30))\r\n\r\n//colorMA = ma30w > ma30w[5] ? color.green : color.red\r\nplot(ma10,title=\"10 EMA\",color=color.white,linewidth=2)\r\nplot(ma21,title=\"21 EMA\",color=color.yellow,linewidth=2)\r\nplot(ma50,title=\"50 EMA\",color=color.orange,linewidth=2)\r\nplot(ma30w,title=\"30 Week MA\",color=color.green,linewidth=2)\r\n\r\n\r\n// =======================\r\n// Inputs\r\n// =======================\r\nmaLength = input.int(30, \"Weekly MA Length\")\r\nlookBack = input.int(4, \"Compare Weeks Ago\", minval=1)\r\n\r\n// =======================\r\n// Weekly MA\r\n// =======================\r\nwma30 = request.security(syminfo.tickerid, \"W\", ta.ema(close, maLength))\r\nwma30_old = request.security(syminfo.tickerid, \"W\", ta.ema(close, maLength)[lookBack])\r\n\r\n// =======================\r\n// Trend Detection\r\n// =======================\r\nisRising = wma30 > wma30_old\r\nisFalling = wma30 < wma30_old\r\n\r\ntrend =\r\n     isRising ? \"🟢 Rising\" :\r\n     isFalling ? \"🔴 Falling\" :\r\n     \"🟡 Flat\"\r\n\r\n// Difference\r\ndiff = wma30 - wma30_old\r\ndiffPct = (diff / wma30_old) * 100\r\n\r\n// =======================\r\n// Table\r\n// =======================\r\nvar table tbl = table.new(position.top_right, 2, 7, border_width=1, border_color=color.white)\r\n\r\nif barstate.islast\r\n\r\n    table.cell(tbl,0,0,\"30W Stage Analysis\",\r\n         bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,1,0,\"\")\r\n\r\n    table.cell(tbl,0,1,\"Current 30WMA\",bgcolor=color.blue,text_color=color.white)\r\n    table.cell(tbl,1,1,str.tostring(wma30, format.mintick),bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,0,2,str.tostring(lookBack)+\" Weeks Ago\",bgcolor=color.blue,text_color=color.white)\r\n    table.cell(tbl,1,2,str.tostring(wma30_old, format.mintick),bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,0,3,\"Difference\",bgcolor=color.blue,text_color=color.white)\r\n    table.cell(tbl,1,3,str.tostring(diff, format.mintick),bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,0,4,\"% Change\",bgcolor=color.blue,text_color=color.white)\r\n    table.cell(tbl,1,4,str.tostring(diffPct,\"#.##\")+\" %\",bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,0,5,\"Trend\",bgcolor=color.blue,text_color=color.white)\r\n\r\n    table.cell(tbl,1,5,\r\n         trend,\r\n         bgcolor=isRising?color.green:isFalling?color.red:color.orange,\r\n         text_color=color.white)\r\n\r\n    stage = isRising and close>wma30 ? \"Stage 2 Candidate\" : \"Not Stage 2\"\r\n\r\n    table.cell(tbl,0,6,\"Stage\",bgcolor=color.blue,text_color=color.white)\r\n    table.cell(tbl,1,6,\r\n         stage,\r\n         bgcolor=stage==\"Stage 2 Candidate\"?color.green:color.red,\r\n         text_color=color.white)',NULL,NULL,NULL,NULL,'2026-10-09 05:02:37','2026-10-09 05:02:37'),(2,'21 cross 50 EMA Pullback + Inside Bar Combo','Trading View Script','//@version=5\r\nindicator(\"EMA Pullback + Inside Bar Combo\", overlay=true)\r\n\r\n// =====================\r\n// === INPUTS ===\r\n// =====================\r\nema10_len = input.int(10, title=\"EMA 10 Length\")\r\nema21_len = input.int(21, title=\"EMA 21 Length\")\r\nema50_len = input.int(50, title=\"EMA 50 Length\")\r\nma30w = request.security(syminfo.tickerid,\"W\",ta.ema(close, 30))\r\nma10w = request.security(syminfo.tickerid,\"W\",ta.ema(close, 10))\r\n\r\ntarget_perc = input.float(20.0, title=\"Target %\") / 100\r\n\r\nuseFlag = input.bool(true, title=\"Show Inside Bar Flag\")\r\n\r\n// =====================\r\n// === EMA SECTION ===\r\n// =====================\r\nema10 = ta.ema(close, ema10_len)\r\nema21 = ta.ema(close, ema21_len)\r\nema50 = ta.ema(close, ema50_len)\r\n\r\nbullish_cross = ta.crossover(ema21, ema50)\r\nprice_touch = low <= ema21 and close > ema21\r\n\r\nvar bool trend_active = false\r\nvar bool inTrade = false\r\nvar float entry_price = na\r\n\r\nif bullish_cross\r\n    trend_active := true\r\n\r\nbuy_signal = trend_active and price_touch and not inTrade\r\n\r\nif buy_signal\r\n    entry_price := close\r\n    inTrade := true\r\n\r\ntarget_price = entry_price * (1 + target_perc)\r\ntarget_hit = inTrade and close >= target_price\r\n\r\nexit_signal = inTrade and close < ema50\r\n\r\nif target_hit or exit_signal\r\n    inTrade := false\r\n    trend_active := false\r\n    entry_price := na\r\n\r\n// =====================\r\n// === INSIDE BAR LOGIC ===\r\n// =====================\r\nisInsideBar = high <= high[1] and low >= low[1]\r\nplotshape(useFlag and isInsideBar, title=\"Inside Bar\", style=shape.flag, color=color.blue)\r\nplot(ma30w,title=\"30 Week MA\",color=color.rgb(0, 87, 209),linewidth=2)\r\nplot(ma10w,title=\"10 Week MA\",color=color.rgb(126, 178, 251),linewidth=2)\r\n// Previous candle inside bar\r\nisPrevInsideBar = high[1] <= high[2] and low[1] >= low[2]\r\n\r\n// Function to get IB levels\r\nf_ibHigh(tf) =>\r\n    request.security(syminfo.tickerid, tf, isPrevInsideBar ? high[1] : na)\r\n\r\nf_ibLow(tf) =>\r\n    request.security(syminfo.tickerid, tf, isPrevInsideBar ? low[1] : na)\r\n\r\n// =====================\r\n// === MULTI TF LEVELS ===\r\n// =====================\r\nintraday = timeframe.isintraday\r\n\r\nplot(intraday ? f_ibHigh(\"60\") : na, title=\"Hourly IB High\", color=color.blue, linewidth=2, style=plot.style_linebr)\r\nplot(intraday ? f_ibLow(\"60\") : na, title=\"Hourly IB Low\", color=color.blue, linewidth=2, style=plot.style_linebr)\r\n\r\nplot(intraday ? f_ibHigh(\"D\") : na, title=\"Daily IB High\", color=color.orange, linewidth=2, style=plot.style_linebr)\r\nplot(intraday ? f_ibLow(\"D\") : na, title=\"Daily IB Low\", color=color.orange, linewidth=2, style=plot.style_linebr)\r\n\r\nplot((intraday or timeframe.isdaily) ? f_ibHigh(\"W\") : na, title=\"Weekly IB High\", color=color.purple, linewidth=3, style=plot.style_linebr)\r\nplot((intraday or timeframe.isdaily) ? f_ibLow(\"W\") : na, title=\"Weekly IB Low\", color=color.purple, linewidth=3, style=plot.style_linebr)\r\n\r\n// =====================\r\n// === PLOTS ===\r\n// =====================\r\nplot(ema10, color=color.white, linewidth=2, title=\"EMA 10\")\r\nplot(ema21, color=color.green, linewidth=2, title=\"EMA 21\")\r\nplot(ema50, color=color.red, linewidth=2, title=\"EMA 50\")\r\n\r\n// =====================\r\n// === SIGNALS ===\r\n// =====================\r\nplotshape(bullish_cross, title=\"WATCH\", location=location.belowbar, color=color.yellow, style=shape.labelup, text=\"WATCH\")\r\n\r\nplotshape(buy_signal, title=\"BUY\", location=location.belowbar, color=color.green, style=shape.labelup, text=\"BUY\")\r\n\r\nplotshape(exit_signal, title=\"EXIT\", location=location.abovebar, color=color.red, style=shape.labeldown, text=\"EXIT\")\r\n\r\nplotshape(target_hit, title=\"TARGET\", location=location.abovebar, color=color.purple, style=shape.labeldown, text=\"TARGET\")\r\n\r\n// =====================\r\n// === ALERTS ===\r\n// =====================\r\nalertcondition(bullish_cross, title=\"Watch Alert\", message=\"21 EMA crossed above 50 EMA\")\r\n\r\nalertcondition(buy_signal, title=\"Buy Alert\", message=\"BUY signal triggered\")\r\n\r\nalertcondition(exit_signal, title=\"Exit Alert\", message=\"EXIT signal triggered\")\r\n\r\nalertcondition(target_hit, title=\"Target Alert\", message=\"Target 20% achieved\")',NULL,NULL,NULL,NULL,'2026-10-09 05:04:00','2026-10-09 05:04:00'),(3,'NSE Links','Links','https://www.nseindia.com/report-detail/eq_security\r\n\r\nhttps://www.nseindia.com/market-data/live-equity-market\r\n\r\nhttps://www.nseindia.com/market-data/volume-gainers-spurts','Screener creation in NSE https://marketlens.nseindia.com/',NULL,NULL,NULL,'2026-10-09 05:41:15','2026-10-09 05:41:15'),(4,'Chroem Extensions for  - https://www.screener.in/','Extensions','ProScreener – Premium Stock Analysis\r\n\r\nScreener.in Better Results Highlighter\r\n\r\nSuperScreener',NULL,NULL,NULL,NULL,'2026-10-09 05:58:26','2026-10-09 05:58:26'),(5,'Dividend Yield STG','STG','Strategy for Dividend Stocks\r\n\r\nOn the basis of this, we can trade in high-dividend stocks.\r\n\r\nIf a stock\'s price is 20% down from the 200 MA, then we can buy it and later sell it from where we bought it.\r\n\r\n[Diagram explanation: Buy when the stock price is approximately 20% below the 200 MA, and sell when the price recovers toward the 200 MA.]\r\n\r\nWe can also observe the price: if, after a 20% decline, it goes up by another 10%, i.e., reaches a 30% recovery level, we will sell collectively.','https://www.screener.in/screens/4022342/dividend-stock/','https://online.fliphtml5.com/kqrgp/xtqa/#p=1','knowledge-center/deUPNddehXok2mqh2y7OAp28SC6KUdeFsPEWG4Ne.png',NULL,'2026-10-09 06:55:03','2026-10-09 07:40:20');
